(function(root,factory){const data=factory();if(typeof module==="object"&&module.exports)module.exports=data;if(root)root.CookingMethodsData=data;})(typeof window!=="undefined"?window:null,function(){"use strict";const db={"version":"2026-10-17","evidence":{"veg":"https://pubmed.ncbi.nlm.nih.gov/30263756/","broc":"https://pubmed.ncbi.nlm.nih.gov/19650196/","brocCounter":"https://pubmed.ncbi.nlm.nih.gov/17995854/","tomato":"https://pubmed.ncbi.nlm.nih.gov/15927929/","lycopene":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7996133/","egg":"https://www.foodauthority.nsw.gov.au/consumer/food-extra-care/eggs-enjoy-safely","vulnerable":"https://www.foodstandards.gov.au/consumer/prevention-of-foodborne-illness/Food-safety-for-vulnerable-populations","chicken":"https://www.foodstandards.gov.au/consumer/prevention-of-foodborne-illness/food-safety-basics","temps":"https://www.foodauthority.nsw.gov.au/consumer/food-safety-home/cooking-temperatures","fish":"https://pubmed.ncbi.nlm.nih.gov/24996368/","fishWet":"https://www.sciencedirect.com/science/article/pii/S0889157525002972","rice":"https://www.fda.gov/food/environmental-contaminants-food/what-you-can-do-limit-exposure-arsenic","arsenic":"https://pubmed.ncbi.nlm.nih.gov/26515534/","beans":"https://www.fda.gov/files/food/published/Bad-Bug-Book-2nd-Edition-%28PDF%29.pdf","legume":"https://pmc.ncbi.nlm.nih.gov/articles/PMC13396823/","fats":"https://www.heartfoundation.au/healthy-living/healthy-eating/fats-oils-and-heart-health","cooking":"https://www.heartfoundation.au/healthy-living/healthy-eating/skills/heart-healthy-cooking-tips","acry":"https://www.foodstandards.gov.au/consumer/chemicals/acrylamide","leftovers":"https://www.foodauthority.nsw.gov.au/consumer/food-extra-care/leftovers","foodSafety":"https://www.foodstandards.gov.au/consumer/prevention-of-foodborne-illness/food-safety-basics","carrot":"https://pubmed.ncbi.nlm.nih.gov/40226756/","enoki":"https://www.foodstandards.gov.au/consumer/prevention-of-foodborne-illness/listeria-monocytogenes-and-imported-fresh-enoki-mushrooms","afcd":"https://www.foodstandards.gov.au/science-data/food-nutrient-databases/afcd/data-files"},"groups":[{"id":"egg","name":"Eggs","group":"Protein","pattern":"\\beggs?\\b|egg[, ]","flags":"i","recommended":"Hard-boil, fully set poach, or gently scramble with minimal olive oil","why":"All supply substantial protein. Method-related added fat and adequate cooking matter more than any proven longevity ranking.","important":"For pregnant, elderly, immunocompromised or young children, use fully cooked eggs; FSANZ suggests both yolk and white firm (~72°C for higher-risk people). Avoid raw egg and runny eggs for these groups.","refs":["egg","vulnerable","cooking"],"options":[{"name":"Hard-boil","advantage":"No added cooking fat; portable for a snack.","tradeoff":"Overcooking affects texture; still nutritious.","tip":"Chill promptly; use a clean uncracked egg."},{"name":"Soft-boil / runny poach","advantage":"Tender, no extra oil needed.","tradeoff":"Runny yolk is a higher food-safety risk for vulnerable people.","tip":"Not a safer choice for vulnerable eaters."},{"name":"Fully set poach","advantage":"No oil needed and can cook through.","tradeoff":"Need enough time for a firm centre.","tip":"Bring centre to safely set, especially for higher-risk eaters."},{"name":"Gently scramble","advantage":"Quick; vegetables may be folded in.","tradeoff":"Butter/cream or excess oil changes overall meal; easy to dry out.","tip":"Use a nonstick pan and a small measured amount of olive oil."},{"name":"Lightly fry","advantage":"Compatible with vegetables and wholegrain toast.","tradeoff":"Added frying fat and hot browned edges vary; not proven inherently worse than boiling.","tip":"Use modest oil and cook the yolk fully if needed."},{"name":"Bake / omelette","advantage":"Easy batch meal with greens.","tradeoff":"Large trays can be unevenly cooked.","tip":"Use a thermometer for thick egg dishes; cook centre through."},{"name":"Raw / in smoothie","advantage":"No theoretical heat-related vitamin losses.","tradeoff":"Salmonella risk; raw egg is not a superior protein strategy.","tip":"Not recommended."}],"certainty":"Safety established; no direct lifespan trial ranks egg methods"},{"id":"chicken","name":"Chicken thigh","group":"Protein","pattern":"chicken thigh|chicken breast|raw chicken|chicken and turkey","flags":"i","recommended":"Bake, steam, poach or stew gently until thoroughly cooked","why":"Moist heat or oven cooking with herbs gives lean protein without deep-frying; temperature matters most.","important":"Check centre with clean probe. FSANZ advises at least 75°C for poultry (NSW Food Authority lists 74°C). Do not wash raw chicken.","refs":["chicken","temps","cooking"],"options":[{"name":"Bake / roast","advantage":"Hands-off batch cooking with vegetables.","tradeoff":"Charring adds unnecessary high-heat exposure.","tip":"Measure the thickest part, not just the browned surface."},{"name":"Poach / simmer","advantage":"No added fat, moist outcome.","tradeoff":"Boiling hard can toughen it.","tip":"Use clean probe to reach safe centre temperature."},{"name":"Stew / slow-cook","advantage":"Tender and economical, with vegetables.","tradeoff":"Slow cookers require adequate heat throughout.","tip":"Check poultry centre at least 75°C before serving."},{"name":"Steam","advantage":"No added oil and easy to portion.","tradeoff":"Flavour needs herbs or sauce.","tip":"Do not assume steaming time alone proves safety."},{"name":"Pan fry / stir-fry","advantage":"Fast in small pieces, little oil.","tradeoff":"Uneven cooking possible; very high heat can scorch.","tip":"Use small pieces and check largest."},{"name":"Deep fry / heavily char","advantage":"Crisp texture.","tradeoff":"More oil and breading; avoid frequent very dark scorching.","tip":"Occasional preference, not a recommended default."}],"certainty":"Food-safety guidance stronger than direct method-longevity evidence"},{"id":"salmon","name":"Salmon / coho fillets","group":"Seafood","pattern":"salmon|coho","flags":"i","recommended":"Gentle oven-bake or steam; use thermometer","why":"Avoid very high-temperature or prolonged frying; steaming has some fish-specific EPA/DHA retention evidence but results vary with species.","important":"NSW Food Authority recommends 63°C fish centre. Omega-3 per portion depends on fish species, cooked yield and oil; the studies weren't necessarily coho salmon.","refs":["fish","fishWet","temps","cooking"],"options":[{"name":"Steam","advantage":"No cooking oil, gentle heat; some wet-heat trials retained more EPA/DHA.","tradeoff":"Species-specific studies cannot be applied as a precise omega-3 percentage to coho.","tip":"Cook fish through and keep it moist."},{"name":"Oven bake / foil","advantage":"Easy, flavoursome, no frying oil.","tradeoff":"High heat/time can dry fish; foil method is not always superior to steam.","tip":"Avoid excessive browning."},{"name":"Poach","advantage":"Low-temperature gentle cooking with aromatics.","tradeoff":"Poaching water may contain escaped soluble compounds.","tip":"Cook until safe throughout."},{"name":"Light pan-sear","advantage":"Acceptable with small unsaturated oil.","tradeoff":"Can increase fat from oil, and scorch edges if overheated.","tip":"Use moderate heat and check thickest part."},{"name":"Air-fry","advantage":"Convenient, usually needs little added oil.","tradeoff":"Hot dry air can overcook omega-3-rich fillets.","tip":"Use lower feasible heat and avoid charring."},{"name":"Deep-fry","advantage":"Crisp coated fish.","tradeoff":"Oil uptake and batter affect dietary pattern.","tip":"Not the regular default."}],"certainty":"Fish cooking literature mixed; no universal omega-3 winner"},{"id":"sardine","name":"Canned sardines","group":"Seafood","pattern":"sardines?|john west.*sardine","flags":"i","recommended":"Eat as supplied; or warm briefly after adding to hot food","why":"Commercial canned sardines are already heat processed; a second cook usually adds no safety benefit and can harm texture.","important":"Use drained edible weight and count soft bones only when actually eaten. Refrigerate leftover opened tins promptly.","refs":["fish","leftovers","fats"],"options":[{"name":"Ready-to-eat drained","advantage":"No second heat exposure, fast lunch.","tradeoff":"Check canned salt and whether bones are eaten.","tip":"Handle opened tins as per label."},{"name":"Warm into cooked grain / sauce","advantage":"Convenient warm meal.","tradeoff":"Additional cooking isn't needed for sterilisation.","tip":"Add near the end."},{"name":"Pan-sear briefly","advantage":"Flavour and crispy edge.","tradeoff":"Can scorch and add oil.","tip":"Not proven superior nutritionally."},{"name":"Deep-fry / char","advantage":"Crisp bite.","tradeoff":"Extra added fat / high heat for already-cooked food.","tip":"Skip as everyday default."}],"certainty":"Direct comparisons for *canned* sardines lacking"},{"id":"broccoli","name":"Broccoli","group":"Vegetables","pattern":"broccoli(?!.*cauliflower)","flags":"i","recommended":"Brief steam or microwave with a splash of water","why":"Several food-specific laboratory studies find better vitamin C/glucosinolate retention than prolonged boiling; cooking lightly improves practicality.","important":"Fresh/frozen and chopping change enzyme activity; sulforaphane results conflict across tests. Nutrient retention is not a demonstrated human longevity outcome.","refs":["broc","brocCounter","veg"],"options":[{"name":"Brief steam","advantage":"Often preserves vitamin C and glucosinolates better than prolonged boiling.","tradeoff":"Not always highest *sulforaphane* because enzymes respond differently.","tip":"Steam until tender-crisp, not mushy."},{"name":"Microwave, minimal water","advantage":"Very short exposure can retain vitamin C.","tradeoff":"Microwave conditions and water/time matter.","tip":"Cover in microwave-safe bowl; stir for even heating."},{"name":"Boil, discard water","advantage":"Easy and safe.","tradeoff":"Soluble vitamin and glucosinolate losses into discarded water.","tip":"Short boil; use liquid in soup if practical."},{"name":"Roast / air-fry","advantage":"Tasty caramelised florets; little oil needed.","tradeoff":"Long high heat may degrade heat-sensitive compounds.","tip":"Avoid blackened tips."},{"name":"Stir-fry","advantage":"Quick with other vegetables.","tradeoff":"Very high heat and long cooking can reduce vitamin C.","tip":"Finish with a little water."},{"name":"Raw, washed","advantage":"Preserves raw vitamin C, crunchy.","tradeoff":"Different glucosinolate conversion; more chewing; GI tolerance varies.","tip":"Wash well, especially when served uncooked."}],"certainty":"Food-specific nutrient studies; no direct lifespan outcomes"},{"id":"cauliflower","name":"Cauliflower","group":"Vegetables","pattern":"cauliflower","flags":"i","recommended":"Brief steam or microwave","why":"As with other brassicas, limiting water and cooking time helps protect soluble vitamins.","important":"Evidence for broccoli does not give a numeric retention for cauliflower; frozen florets are often already blanched.","refs":["veg","broc"],"options":[{"name":"Steam","advantage":"Minimal leaching.","tradeoff":"May soften unevenly.","tip":"Check tenderness."},{"name":"Microwave","advantage":"Fast with minimal water.","tradeoff":"Overcooking makes it wet.","tip":"Cover and stir."},{"name":"Roast","advantage":"Nutty flavour can improve vegetable intake.","tradeoff":"Dark charring/long heat.","tip":"Use moderate oven and small oil."},{"name":"Boil","advantage":"Fast for puree/soup.","tradeoff":"Water-soluble nutrients may leach.","tip":"Keep cooking liquid when making soup."},{"name":"Raw, washed","advantage":"Crisp snack.","tradeoff":"May aggravate digestive symptoms in some.","tip":"Cut to safe bite sizes."}],"certainty":"Food-specific evidence mixed; choice is conditional"},{"id":"mixed-brassicas","name":"Frozen broccoli and cauliflower mix","group":"Vegetables","pattern":"broccoli.?cauliflower","flags":"i","recommended":"Steam or microwave from frozen as directed","why":"Avoid thawing on the counter; brief cooking of the whole mix reduces leaching compared with long boiling.","important":"Not the same as fresh unblanched broccoli; use package directions.","refs":["veg","foodSafety"],"options":[{"name":"Steam from frozen","advantage":"No needless cooking-water loss.","tradeoff":"Different sized pieces cook unevenly.","tip":"Follow pack directions; check all pieces hot."},{"name":"Microwave","advantage":"Efficient; limited water.","tradeoff":"Hot spots require stirring.","tip":"Cover and allow standing time."},{"name":"Roast from frozen","advantage":"Enjoyable browned texture.","tradeoff":"Longer/high heat.","tip":"Don't char."},{"name":"Boil","advantage":"Simple.","tradeoff":"More water-soluble leaching.","tip":"Use liquid in a soup if practical."}],"certainty":"Food-specific evidence mixed; choice is conditional"},{"id":"spinach","name":"Spinach","group":"Leafy greens","pattern":"spinach","flags":"i","recommended":"Quick wilt, brief steam or microwave; alternate with washed raw leaves","why":"Brief heating softens large leaves and can reduce some oxalate; raw preserves some vitamin C and texture.","important":"Spinach is not a dependable calcium source because of oxalates; frozen spinach requires thorough heating as directed.","refs":["veg","afcd"],"options":[{"name":"Raw, washed","advantage":"Convenient, minimal heat-sensitive vitamin loss.","tradeoff":"Bulk is hard to eat in large amounts; wash thoroughly.","tip":"Keep chilled."},{"name":"Briefly wilt in pan","advantage":"Compact, easy to combine with egg.","tradeoff":"Added fats / long heating unnecessary.","tip":"Use a splash of water."},{"name":"Steam / microwave","advantage":"Quick, relatively limited leaching.","tradeoff":"Long cooking degrades vitamin C.","tip":"Heat evenly."},{"name":"Boil, drain","advantage":"Can reduce water-soluble oxalates.","tradeoff":"Also removes some vitamin C and minerals.","tip":"A trade-off, not a blanket healthiest."},{"name":"Deep-fry","advantage":"Crispy preparation.","tradeoff":"Extra frying oil.","tip":"Not needed for everyday greens."}],"certainty":"Food-specific evidence mixed; choice is conditional"},{"id":"kale","name":"Kale","group":"Leafy greens","pattern":"kale","flags":"i","recommended":"Brief steam or wilt; finely shred raw when safe and liked","why":"Minimises leaching and can make tough leaves easier to eat.","important":"No evidence kale requires a raw-only preparation to be healthy.","refs":["veg","broc"],"options":[{"name":"Steam","advantage":"Tender with modest vitamin loss.","tradeoff":"Overcook and it softens.","tip":"2–5 min depends on leaf."},{"name":"Pan wilt / stir-fry","advantage":"Good with garlic and modest olive oil.","tradeoff":"Long, intense heat can destroy sensitive vitamins.","tip":"Quickly wilt."},{"name":"Raw, massaged and washed","advantage":"Maintains texture and heat-sensitive nutrients.","tradeoff":"Tough and strong taste.","tip":"Shred thinly."},{"name":"Boil","advantage":"Easier to soften stems.","tradeoff":"Discarded water loses nutrients.","tip":"Use soup liquid."}],"certainty":"Food-specific evidence mixed; choice is conditional"},{"id":"peas","name":"Green peas","group":"Vegetables","pattern":"baby peas|\\bpeas\\b","flags":"i","recommended":"Steam or microwave from frozen","why":"Good legume/vegetable source; short cooking with minimal water protects soluble vitamins.","important":"Frozen peas may be blanched, not necessarily ready-to-eat raw; follow packet directions.","refs":["veg","foodSafety"],"options":[{"name":"Steam","advantage":"Easy and fast.","tradeoff":"Avoid overcooking.","tip":"Heat from frozen."},{"name":"Microwave","advantage":"Minimal water needed.","tradeoff":"Stir to distribute heat.","tip":"Use covered microwave-safe dish."},{"name":"Boil and drain","advantage":"Simple.","tradeoff":"Soluble nutrients enter water.","tip":"Short boil."},{"name":"Add to soup","advantage":"Retains any escaped nutrients in liquid.","tradeoff":"Long simmer affects vitamin C.","tip":"Add near finish."}],"certainty":"Food-specific evidence mixed; choice is conditional"},{"id":"green-beans","name":"Green beans","group":"Vegetables","pattern":"green beans","flags":"i","recommended":"Steam or quick sauté","why":"Minimal water losses, pleasant crispness and can be eaten with the meal's other vegetables.","important":"Cook to a texture safe for the person eating.","refs":["veg","cooking"],"options":[{"name":"Steam","advantage":"Minimal water, crisp.","tradeoff":"Long steam becomes limp.","tip":"Cook through to tender."},{"name":"Stir-fry","advantage":"Tasty with small oil.","tradeoff":"Over-fry can scorch.","tip":"Use a splash of water."},{"name":"Boil","advantage":"Accessible.","tradeoff":"Leaching if drained.","tip":"Keep brief."},{"name":"Roast","advantage":"Convenient with sheet-pan chicken.","tradeoff":"Ends may char.","tip":"Check often."}],"certainty":"Food-specific evidence mixed; choice is conditional"},{"id":"carrot","name":"Carrots","group":"Vegetables","pattern":"carrots?|carrot sticks","flags":"i","recommended":"Alternate raw and gently cooked; add a little unsaturated fat to meals","why":"Raw offers crunch and fibre; heating/pureeing can improve accessibility of carotenoids while potentially decreasing vitamin C.","important":"Bioavailability data are nutrient-specific, not proof cooked carrots always outperform raw.","refs":["carrot","veg","fats"],"options":[{"name":"Raw, washed","advantage":"Crunchy, minimal heat loss.","tradeoff":"Carotenoid extraction from whole tissue may be limited.","tip":"Great snack; cut appropriately."},{"name":"Steam","advantage":"Softens and increases accessibility of carotenoids.","tradeoff":"Some vitamin C lost.","tip":"Serve with a meal containing some fat."},{"name":"Roast","advantage":"Palatable; encourages vegetable intake.","tradeoff":"Avoid dark edges and excess oil.","tip":"Use moderate heat."},{"name":"Microwave","advantage":"Fast and limited water.","tradeoff":"Uneven cooking.","tip":"Stir and cover."},{"name":"Boil","advantage":"Soft texture.","tradeoff":"Water-soluble nutrients may be lost.","tip":"Keep liquid if soup."},{"name":"Blend / puree","advantage":"Disrupts plant cells.","tradeoff":"Juicing strains off fibre, unlike a puree.","tip":"Prefer whole/pureed over strained juice for fibre."}],"certainty":"Food-specific evidence mixed; choice is conditional"},{"id":"pumpkin","name":"Pumpkin / butternut","group":"Vegetables","pattern":"pumpkin|butternut","flags":"i","recommended":"Bake or steam; include modest unsaturated fat in meal","why":"Soft cooked pumpkin supplies accessible carotenoid-rich vegetables; cooking choice should suit the recipe.","important":"No direct trial shows roasted pumpkin extends life more than steamed pumpkin.","refs":["veg","carrot"],"options":[{"name":"Steam","advantage":"No oil required and softens evenly.","tradeoff":"Milder taste.","tip":"Serve with protein."},{"name":"Roast","advantage":"Enhances flavour and may encourage eating.","tradeoff":"Very dark char adds no demonstrated advantage.","tip":"Roast tender, not black."},{"name":"Microwave","advantage":"Quickly softens cubes.","tradeoff":"Stir for even cooking.","tip":"Cover loosely."},{"name":"Boil into soup","advantage":"Uses cooking liquid, minimising discarded nutrients.","tradeoff":"Long boil still harms some sensitive vitamins.","tip":"Keep liquid."}],"certainty":"Food-specific evidence mixed; choice is conditional"},{"id":"sweet-potato","name":"Sweet potato","group":"Vegetables","pattern":"sweet potato","flags":"i","recommended":"Bake, steam or microwave until tender; avoid very dark browning","why":"Carotenoid-rich food; gentle methods avoid unnecessary charring; some cooking makes starch digestible.","important":"Cooking changes starch response, which also depends on portion and meal context. Acrylamide guidance mainly concerns starchy foods browned at high heat.","refs":["veg","acry"],"options":[{"name":"Steam","advantage":"Moist and no added oil.","tradeoff":"No browned flavour.","tip":"Cook until soft."},{"name":"Bake","advantage":"Good texture and aroma.","tradeoff":"Very dark browning isn't necessary.","tip":"Use moderate temperature."},{"name":"Microwave","advantage":"Fast and minimal water.","tradeoff":"Uneven centres can stay hard.","tip":"Pierce skin, rotate and test."},{"name":"Boil","advantage":"Simple for mash or curry.","tradeoff":"Soluble nutrients can leach.","tip":"Use in soup or curry."},{"name":"Deep-fry","advantage":"Crisp fries.","tradeoff":"Added oil; prolonged dark browning.","tip":"Not a routine default."}],"certainty":"Food-specific evidence mixed; choice is conditional"},{"id":"capsicum","name":"Red capsicum","group":"Vegetables","pattern":"capsicum","flags":"i","recommended":"Eat well-washed raw or quick-cook","why":"Raw capsicum protects much vitamin C; short stir-fry adds flavour and variety.","important":"Other dishes and total vegetable intake matter much more than a claimed optimum pan temperature.","refs":["veg","cooking"],"options":[{"name":"Raw, washed","advantage":"Retains sensitive vitamin C and crunch.","tradeoff":"Wash and store safely.","tip":"Slice for bowls."},{"name":"Brief stir-fry","advantage":"Palatable and quick.","tradeoff":"Some heat-sensitive vitamin loss.","tip":"Keep slightly crisp."},{"name":"Roast","advantage":"Sweet flavour and soft texture.","tradeoff":"Long heating changes vitamin C.","tip":"Avoid burnt skin."},{"name":"Boil","advantage":"Softens.","tradeoff":"Nutrient leaching.","tip":"Prefer to simmer in retained sauce."}],"certainty":"Food-specific evidence mixed; choice is conditional"},{"id":"zucchini","name":"Zucchini","group":"Vegetables","pattern":"zucchini","flags":"i","recommended":"Quick sauté, steam or roast, not long water-boil","why":"Short cooking preserves texture and reduces leaching.","important":"No convincing clinical study ranks zucchini methods for lifespan.","refs":["veg","cooking"],"options":[{"name":"Sauté","advantage":"Quick, tasty with small oil.","tradeoff":"Oil amount matters.","tip":"Stop tender-crisp."},{"name":"Steam","advantage":"Simple, no oil.","tradeoff":"Mushy when prolonged.","tip":"Short cook."},{"name":"Roast","advantage":"Browns and concentrates flavour.","tradeoff":"Long cooking dries it out.","tip":"Moderate oven."},{"name":"Boil","advantage":"Can work in soup.","tradeoff":"Watery and leaching if drained.","tip":"Keep broth."},{"name":"Raw, washed","advantage":"Cool salads.","tradeoff":"Personal tolerance and hygiene.","tip":"Thin slices."}],"certainty":"Food-specific evidence mixed; choice is conditional"},{"id":"tomato","name":"Tomatoes / canned diced tomatoes","group":"Vegetables","pattern":"tomat|spc diced","flags":"i","recommended":"Raw plus gently cooked in a little olive oil","why":"Heating and olive oil increase absorbable lycopene in small human feeding trials; raw retains more heat-sensitive vitamin C.","important":"Increased blood lycopene is a surrogate, not proven longer life. Canned no-added-salt tomatoes are useful.","refs":["tomato","lycopene","veg"],"options":[{"name":"Raw, washed","advantage":"Fresh taste and raw vitamin C.","tradeoff":"Lycopene may be less accessible.","tip":"Combine with other foods."},{"name":"Gently simmer with olive oil","advantage":"Human trial found higher circulating lycopene.","tradeoff":"Heating reduces some vitamin C.","tip":"Use modest oil and no-added-salt tomatoes."},{"name":"Roast","advantage":"Concentrated flavour and carotenoids.","tradeoff":"High temperature may degrade sensitive nutrients.","tip":"Avoid blackening."},{"name":"Microwave/simmer sauce","advantage":"Convenient, especially with cooked beans.","tradeoff":"Overcooking unnecessary.","tip":"Keep tomato liquid in dish."},{"name":"Deep-fry","advantage":"Unusual use.","tradeoff":"Extra oil without demonstrated advantage.","tip":"Not a priority."}],"certainty":"Small feeding trials for lycopene; no clinical lifespan comparison"},{"id":"mushroom","name":"Common mushrooms","group":"Vegetables","pattern":"mushrooms?|cup mushrooms","flags":"i","recommended":"Cook briefly in pan, oven or microwave","why":"Improves texture and taste, allowing use as a vegetable-like food.","important":"Enoki mushrooms require different safety handling: do not generalise fresh cup mushroom advice to uncooked enoki.","refs":["cooking","enoki"],"options":[{"name":"Sauté","advantage":"Classic and easy with a small amount of olive oil.","tradeoff":"May release moisture; high heat can scorch.","tip":"Cook until hot and tender."},{"name":"Roast","advantage":"Concentrates flavour.","tradeoff":"Over-roasting dries.","tip":"Moderate heat."},{"name":"Microwave","advantage":"No added oil needed.","tradeoff":"Texture is different.","tip":"Cook evenly."},{"name":"Simmer","advantage":"Incorporates into soup and uses liquid.","tradeoff":"Milder taste.","tip":"Keep broth."},{"name":"Raw","advantage":"Sometimes used in salads.","tradeoff":"Not universally appropriate; enoki must NOT be raw.","tip":"For high-risk eaters prefer fully cooked."}],"certainty":"Food-specific evidence mixed; choice is conditional"},{"id":"onion","name":"Onions","group":"Vegetables","pattern":"onion","flags":"i","recommended":"Gently soften or quick sauté","why":"Easy flavour without salt; retain browning at moderate levels rather than char.","important":"Cooking effects on individual phytochemicals do not directly establish longevity gains.","refs":["cooking","veg"],"options":[{"name":"Raw, sliced","advantage":"Pungent and crunchy.","tradeoff":"Can irritate digestion.","tip":"Wash and handle cleanly."},{"name":"Gently sauté","advantage":"Sweeter flavour in small oil.","tradeoff":"More oil if caramelising heavily.","tip":"Use medium heat."},{"name":"Simmer","advantage":"Adds flavour to soup and retains liquid.","tradeoff":"Long heat changes aromatic compounds.","tip":"Keep broth."},{"name":"Roast","advantage":"Convenient with tray vegetables.","tradeoff":"Dark char is avoidable.","tip":"Roast until golden, not black."},{"name":"Deep-fry","advantage":"Onion rings.","tradeoff":"Oil/batter changes overall meal.","tip":"Not a default."}],"certainty":"Food-specific evidence mixed; choice is conditional"},{"id":"garlic","name":"Garlic","group":"Aromatics","pattern":"garlic","flags":"i","recommended":"Chop and gently add near the end or cook briefly","why":"Garlic adds flavour without salt; high heat alters sulfur compounds.","important":"Proposed enzyme mechanisms are mostly laboratory data; no validated '10-minute rest = longevity' rule.","refs":["cooking","fats"],"options":[{"name":"Finely chopped, raw","advantage":"Strong aroma, no heat loss.","tradeoff":"May be harsh on stomach; safe handling.","tip":"Use in a fresh dressing."},{"name":"Gently sauté","advantage":"Good flavour.","tradeoff":"Scorches quickly.","tip":"Add after onions."},{"name":"Add late to soup","advantage":"Fragrant and avoids prolonged heating.","tradeoff":"Strongness depends on timing.","tip":"Simmer through if desired."},{"name":"Roast cloves","advantage":"Mellow, spreadable.","tradeoff":"Long heat changes compounds.","tip":"Avoid burned garlic."}],"certainty":"Food-specific evidence mixed; choice is conditional"},{"id":"ginger","name":"Fresh ginger","group":"Aromatics","pattern":"ginger","flags":"i","recommended":"Grate fresh or briefly simmer","why":"Adds flavour to sauces, stir-fries and curries; no evidence that one heat method maximises longevity.","important":"Concentrated extracts/supplements aren't equivalent to cooking quantities.","refs":["cooking","afcd"],"options":[{"name":"Fresh grated","advantage":"Bright fresh flavour.","tradeoff":"Stronger bite.","tip":"Use washed/peeled."},{"name":"Quick stir-fry","advantage":"Aromatic.","tradeoff":"Burns easily.","tip":"Start at modest heat."},{"name":"Simmer","advantage":"Mellower flavour in soups.","tradeoff":"Long heat changes components.","tip":"Add when preferred."},{"name":"Roast","advantage":"Deeper flavour.","tradeoff":"Avoid blackening.","tip":"Roast with vegetables."}],"certainty":"Food-specific evidence mixed; choice is conditional"},{"id":"lemon","name":"Lemon / lemon juice","group":"Fruit","pattern":"lemon","flags":"i","recommended":"Use raw juice after cooking, or simmer when flavour suits","why":"Fresh addition avoids heat-sensitive vitamin C loss and can replace added salt.","important":"Small lemon servings cannot be assumed to cover daily vitamin C or iron needs; simmering is also fine.","refs":["veg","cooking"],"options":[{"name":"Squeeze raw over hot food","advantage":"Fresh flavour, minimal thermal vitamin loss.","tradeoff":"Acidity may not suit everyone.","tip":"Add just before eating."},{"name":"Simmer in sauce","advantage":"Useful aroma and acidity.","tradeoff":"Some heat-sensitive vitamin C lost.","tip":"Keep zest clean if used."},{"name":"Roast slices","advantage":"Convenient with chicken/fish.","tradeoff":"Some juice evaporates.","tip":"Don't burn."}],"certainty":"Food-specific evidence mixed; choice is conditional"},{"id":"quinoa","name":"Quinoa","group":"Grains","pattern":"quinoa","flags":"i","recommended":"Rinse as directed, simmer in measured water, fluff","why":"Cooking makes grain digestible; pressure-cooking and rice-cooking are options; water ratio determines texture.","important":"Rinsing removes some surface saponins; cannot assume extra boiling is inherently more nutritious.","refs":["legume","cooking"],"options":[{"name":"Absorption simmer","advantage":"No cooking water thrown away.","tradeoff":"Time/ratio matter.","tip":"Cook fully and fluff."},{"name":"Boil like pasta, drain","advantage":"Forgiving texture.","tradeoff":"Discarded cooking water may lose minerals.","tip":"Useful if ratio unknown."},{"name":"Pressure cook","advantage":"Convenient and tender.","tradeoff":"Different equipment timing.","tip":"Follow safe instructions."},{"name":"Toast dry before simmer","advantage":"Nutty flavour.","tradeoff":"Very dark scorching is avoidable.","tip":"Brown lightly."},{"name":"Raw, uncooked","advantage":"Not an appropriate staple preparation.","tradeoff":"Digestibility and cleanliness.","tip":"Cook."}],"certainty":"Food-specific evidence mixed; choice is conditional"},{"id":"rice","name":"Brown rice","group":"Grains","pattern":"brown.*rice|sunrice","flags":"i","recommended":"Cook thoroughly; choose absorption or excess-water boiling for your priority","why":"Absorption limits discarded nutrients; boiling in 6–10 parts water and draining reduces inorganic arsenic 40–60% in FDA studies, while losing some enriched B vitamins and iron.","important":"Brown rice has variable arsenic exposure; rotate with quinoa/oats rather than treating a single cooking technique as complete protection. Cool cooked rice promptly and refrigerate no more than two days (NSW).","refs":["rice","arsenic","leftovers"],"options":[{"name":"Absorption cook","advantage":"Retains ingredients dissolved in water.","tradeoff":"Does not deliberately remove much arsenic.","tip":"Use correct water ratio, cook fully."},{"name":"Excess-water boil & drain","advantage":"Can reduce inorganic arsenic by about 40–60% depending on rice.","tradeoff":"May lose nutrients, especially enriched white/parboiled rice.","tip":"6–10 parts water; drain after fully cooking."},{"name":"Pressure cooker","advantage":"Convenient, energy efficient.","tradeoff":"Arsenic reduction not interchangeable with draining.","tip":"Follow cooker instructions."},{"name":"Microwave / rice cooker","advantage":"Convenient.","tradeoff":"Reheating/storage safety matters more than appliance.","tip":"Chill in shallow portions within 2 hours."},{"name":"Fried rice from leftovers","advantage":"Tasty with vegetables.","tradeoff":"Leftover rice can grow B. cereus if mishandled.","tip":"Use correctly chilled rice; reheat steaming, once."}],"certainty":"Quantified arsenic and nutrient trade-offs; not a universal winner"},{"id":"oats","name":"Rolled oats","group":"Grains","pattern":"rolled oats","flags":"i","recommended":"Cook into porridge or soak safely in fridge overnight","why":"Both approaches keep fibre, including beta-glucan; the decisive differences are texture, enjoyment and safe storage rather than a proven best longevity method.","important":"Overnight oats must be refrigerated below 5°C and prepared with appropriate ready-to-eat toppings.","refs":["cooking","leftovers"],"options":[{"name":"Porridge, gently cooked","advantage":"Warm, easy to digest.","tradeoff":"Added sugar/toppings determine nutrition.","tip":"Cook with water or calcium-fortified soy."},{"name":"Overnight soaked, refrigerated","advantage":"Convenient; no cooking energy.","tradeoff":"Must be safely refrigerated; not shelf-stable.","tip":"Cover and chill at least 6 hours."},{"name":"Microwave porridge","advantage":"Fast and little nutrient leaching.","tradeoff":"Can boil over.","tip":"Stir and cool."},{"name":"Dry toasted granola","advantage":"Crunchy.","tradeoff":"Adding lots of sugar/oil changes diet; dark browning.","tip":"Lightly toast."},{"name":"Unsoaked dry oats","advantage":"Safe in some foods but tough.","tradeoff":"Not universally pleasant.","tip":"Prefer cooked or soaked."}],"certainty":"Food-specific evidence mixed; choice is conditional"},{"id":"lentil","name":"Red split lentils","group":"Legumes","pattern":"lentil","flags":"i","recommended":"Boil/simmer until soft or pressure-cook; retain broth for soups","why":"Heating improves digestibility and lowers heat-sensitive antinutrients; split red lentils usually don't need soaking.","important":"Do not eat dried lentils raw; salt and oil additions often matter more than microscopic vitamin differences.","refs":["legume","foodSafety"],"options":[{"name":"Simmer thoroughly","advantage":"Affordable, excellent for soups; keep liquid.","tradeoff":"Prolonged heat can reduce some vitamins.","tip":"Cook until tender."},{"name":"Pressure cook","advantage":"Time saving, inactivates antinutrients.","tradeoff":"Over-softens quickly.","tip":"Follow appliance directions."},{"name":"Soak then simmer","advantage":"May shorten time for some lentils.","tradeoff":"Usually unnecessary for split red lentils; discard of soak water loses some compounds.","tip":"Optional, not required."},{"name":"Roast cooked lentils","advantage":"Texture variety.","tradeoff":"Do not dry raw lentils and claim cooked.","tip":"Cook first."},{"name":"Raw / soaked only","advantage":"Not adequately cooked.","tradeoff":"Safety and digestibility issues.","tip":"Do not use."}],"certainty":"Food-specific evidence mixed; choice is conditional"},{"id":"kidney","name":"Kidney beans","group":"Legumes","pattern":"kidney beans","flags":"i","recommended":"Use commercially canned cooked beans, or hard-boil dried beans adequately","why":"Red kidney lectin is a food-safety issue, not a longevity optimisation choice.","important":"FDA warns dried kidney beans in inadequately heated slow cookers may cause poisoning. Soak then boil vigorously for at least 30 minutes before slow cooking; canned beans are already cooked.","refs":["beans","legume"],"options":[{"name":"Rinse canned, add to soup/chilli","advantage":"Pre-cooked and convenient.","tradeoff":"Check sodium labels; rinsing changes sodium.","tip":"Heat to serving temperature."},{"name":"Soak dried then vigorous boil ≥30 min","advantage":"Adequately inactivates lectins.","tradeoff":"Requires planning; do not undercook.","tip":"Do NOT start from raw in a slow cooker."},{"name":"Pressure cook dried","advantage":"Can be effective with correct validated times.","tradeoff":"Settings vary by appliance; no blind time guarantee.","tip":"Use manufacturer guidance; ensure properly cooked."},{"name":"Slow cook raw soaked beans","advantage":"No reliable toxin destruction when too cool.","tradeoff":"Can increase toxin activity before inactivation.","tip":"Avoid."},{"name":"Raw/soaked only","advantage":"Dangerous.","tradeoff":"Lectin exposure.","tip":"Never serve."}],"certainty":"Safety based on FDA PHA risk; not appropriate to rank by vitamin retention"},{"id":"chickpea","name":"Chickpeas","group":"Legumes","pattern":"chickpeas?","flags":"i","recommended":"Rinse pre-cooked canned; or soak and boil dry until tender","why":"Safe and nutritious after proper cooking; hummus should be made and stored hygienically.","important":"For vulnerable people, chilled ready-to-eat hummus/tahini needs extra food-safety precautions.","refs":["legume","vulnerable"],"options":[{"name":"Canned, rinse and serve","advantage":"Already cooked, fast.","tradeoff":"Salt may vary; use no-added-salt if possible.","tip":"Follow opened-can refrigeration."},{"name":"Simmer dried soaked chickpeas","advantage":"Creates tender legumes.","tradeoff":"Requires enough heat and time.","tip":"Cook until soft throughout."},{"name":"Pressure-cook soaked","advantage":"Efficient.","tradeoff":"Texture/timing equipment-dependent.","tip":"Use directions."},{"name":"Roast *cooked* chickpeas","advantage":"Crunchy snack.","tradeoff":"High roasting may dry out / add oil.","tip":"Cook first."},{"name":"Raw / soaked only","advantage":"Not adequately digested/cooked.","tradeoff":"No safety advantage.","tip":"Avoid."}],"certainty":"Food-specific evidence mixed; choice is conditional"},{"id":"black-bean","name":"Black beans","group":"Legumes","pattern":"black beans","flags":"i","recommended":"Canned, rinsed and gently reheated; or properly cook dried beans","why":"Legumes add fibre and protein; no strong evidence pan-frying beats gentle simmering.","important":"Commercial tins are pre-cooked. Prefer no-added-salt options when possible.","refs":["legume","cooking"],"options":[{"name":"Canned, drain/rinse","advantage":"Convenient, safe and no extra oil.","tradeoff":"Sodium depends on product.","tip":"Use in salad/chilli."},{"name":"Gently simmer","advantage":"Keeps legumes and sauce together.","tradeoff":"Some vitamins are heat sensitive.","tip":"Warm until hot."},{"name":"Pressure cook dried","advantage":"Efficient when properly softened.","tradeoff":"Needs appropriate recipe and pressure.","tip":"Cook fully."},{"name":"Roast pre-cooked","advantage":"Crunchy texture.","tradeoff":"Can dry out, extra oil.","tip":"Avoid charring."},{"name":"Raw / undercooked","advantage":"Not appropriate.","tradeoff":"Legume lectin/antinutrient considerations.","tip":"Cook thoroughly."}],"certainty":"Food-specific evidence mixed; choice is conditional"},{"id":"tofu","name":"Firm / hard tofu","group":"Protein","pattern":"tofu","flags":"i","recommended":"Gently pan-sear, bake, steam or simmer; choose a calcium-labelled product","why":"Tofu is already processed, edible in many forms, and suitable for varied cooking; calcium content depends on coagulant and label, not cooking method.","important":"Do not falsely claim Evergreen calcium from ingredient 'calcium sulphate' without quantitative label. Soy allergens; refrigerate appropriately.","refs":["afcd","fats","foodSafety"],"options":[{"name":"Steam / simmer in curry","advantage":"No added oil; easy batch meal.","tradeoff":"Can be bland if not seasoned.","tip":"Keep sauce, cook through as needed."},{"name":"Oven bake","advantage":"Firm, handy for portions.","tradeoff":"Drying at high temperature.","tip":"Small measured oil."},{"name":"Pan-sear / stir-fry","advantage":"Good browned flavour.","tradeoff":"Extra oil and prolonged scorching.","tip":"Moderate heat."},{"name":"Air fry","advantage":"Crisp with little oil.","tradeoff":"May become dry.","tip":"Watch timing."},{"name":"Deep fry","advantage":"Crisp bite.","tradeoff":"Higher fat absorption.","tip":"Not everyday default."},{"name":"Chilled/uncooked","advantage":"Many packaged cooked/ready-to-eat tofu products allow this.","tradeoff":"Must follow storage/ready-to-eat labeling, especially for higher-risk eaters.","tip":"Check pack before using raw."}],"certainty":"Generic studies, no demonstrated health outcome ordering"},{"id":"walnuts","name":"Walnuts","group":"Nuts & seeds","pattern":"walnut","flags":"i","recommended":"Eat raw/untoasted, or lightly toast if desired","why":"Raw nuts avoid extra oxidation from repeated intense heat; occasional light toasting improves flavour.","important":"ALA omega-3 can oxidise in heat/light; precise health outcome difference raw vs toasted walnuts unknown.","refs":["fats","afcd"],"options":[{"name":"Raw/untoasted","advantage":"Quick, no added oil/salt.","tradeoff":"Shorter shelf life after chopping.","tip":"Store airtight away from heat."},{"name":"Light toast","advantage":"More aroma.","tradeoff":"Some heat-sensitive fats/compounds can degrade.","tip":"Toast briefly, don't blacken."},{"name":"Add after cooking","advantage":"Avoid additional long heat exposure.","tradeoff":"Texture remains crunchy.","tip":"Use after reheating."},{"name":"Candy / deep-fry","advantage":"Sweet/crisp.","tradeoff":"Adds sugar and fat.","tip":"Not the usual default."}],"certainty":"Food-specific evidence mixed; choice is conditional"},{"id":"flax","name":"Ground flaxseed / linseed meal","group":"Nuts & seeds","pattern":"flaxseed|linseed meal","flags":"i","recommended":"Use freshly ground or stored ground, added after cooking","why":"Grinding makes seed contents accessible; keep airtight and cool to reduce oxidation.","important":"Claims that brief baking destroys all ALA are overstated; exact human health outcome for heat timing is unknown.","refs":["fats","afcd"],"options":[{"name":"Ground, add at serving","advantage":"Avoids unnecessary high-heat exposure.","tradeoff":"Some people dislike texture.","tip":"Store sealed and cool."},{"name":"Mix into overnight oats","advantage":"Easy fibre/ALA addition.","tradeoff":"Must refrigerate safely.","tip":"Use measured amounts."},{"name":"Bake into bread","advantage":"Convenient.","tradeoff":"Heat affects some compounds; ALA not instantly lost.","tip":"Avoid heavy browning."},{"name":"Whole dry seeds","advantage":"Adds texture.","tradeoff":"Many may pass through undigested.","tip":"Grinding usually more practical."}],"certainty":"Food-specific evidence mixed; choice is conditional"},{"id":"chia","name":"Chia seeds","group":"Nuts & seeds","pattern":"chia seeds","flags":"i","recommended":"Soak in oats or add to yoghurt; ground also works","why":"No heating required to obtain fibre and ALA; soaking changes gel texture, not proven to add lifespan.","important":"Avoid inhaling or swallowing large amounts of dry chia followed by fluid if swallowing difficulties exist.","refs":["fats","afcd"],"options":[{"name":"Hydrate in overnight oats","advantage":"Soft gel, easy portion.","tradeoff":"Food-safety needs refrigeration.","tip":"Soak covered in fridge."},{"name":"Sprinkle on moist meal","advantage":"Convenient.","tradeoff":"Whole seeds may be harder to chew.","tip":"Use small measured portion."},{"name":"Ground","advantage":"Accessible texture and oils.","tradeoff":"Can oxidise in storage.","tip":"Use fresh, keep airtight."},{"name":"Bake","advantage":"Possible in muffins/bread.","tradeoff":"Some heat exposure; whole recipe matters.","tip":"Avoid added sugar-heavy bake."},{"name":"Dry spoonful then water","advantage":"No benefit.","tradeoff":"Possible swallowing/expansion risk.","tip":"Avoid."}],"certainty":"Food-specific evidence mixed; choice is conditional"},{"id":"oil","name":"Olive oil / EVOO","group":"Fats & seasonings","pattern":"olive oil|\\bevoo\\b","flags":"i","recommended":"Use measured amounts, dress or cook without overheating","why":"Unsaturated-fat substitution is much better evidenced than a specific 'smoke point = healthiest' claim.","important":"Olive oil remains useful for normal home cooking; avoid repeatedly heating oil to smoking or deep-frying every meal.","refs":["fats","cooking"],"options":[{"name":"Cold dressing / finishing","advantage":"Retains more delicate phenolics and aroma.","tradeoff":"Doesn't make added calories zero.","tip":"Measure if monitoring energy."},{"name":"Moderate sauté","advantage":"Heart-healthy unsaturated cooking fat.","tradeoff":"Overheating alters oil compounds.","tip":"Avoid smoke."},{"name":"Roasting drizzle","advantage":"Helps palatability / carotenoid absorption.","tradeoff":"Oil quantities add up.","tip":"Measure modestly."},{"name":"Deep fry / reuse oil","advantage":"Crispy texture.","tradeoff":"Large fat uptake and overheated reused oils.","tip":"Not regular default."}],"certainty":"Food-specific evidence mixed; choice is conditional"},{"id":"berries","name":"Mixed berries","group":"Fruit","pattern":"berr(y|ies)|blueberr|strawberr","flags":"i","recommended":"Washed fresh or prepared frozen according to label; vulnerable eaters: thoroughly cook frozen berries, cool safely","why":"Raw fresh may retain vitamin C; cooked frozen fruit can be a safer option for medically vulnerable populations.","important":"Frozen berries can carry viruses; thawing does not kill pathogens. Healthy-adult and vulnerable guidance differ.","refs":["vulnerable","foodSafety","veg"],"options":[{"name":"Washed fresh","advantage":"Convenient and vitamin-rich.","tradeoff":"Perishable, need washing.","tip":"Refrigerate promptly."},{"name":"Commercial frozen per instructions","advantage":"Convenient year-round.","tradeoff":"Raw frozen berries have infection risks especially for vulnerable eaters.","tip":"Follow packaging and risk-specific guidance."},{"name":"Thoroughly heat then chill","advantage":"Safer higher-risk preparation.","tradeoff":"Heat may reduce some vitamin C.","tip":"Cool promptly in a shallow container."},{"name":"Bake / compote","advantage":"Pleasant alternative.","tradeoff":"Heat changes vitamin C, sugar often added unnecessarily.","tip":"Avoid extra sugar."},{"name":"Just thaw frozen for vulnerable eater","advantage":"Not a pathogen-killing step.","tradeoff":"Risk remains.","tip":"Use a cooked alternative."}],"certainty":"Food-specific evidence mixed; choice is conditional"},{"id":"apple","name":"Apples","group":"Fruit","pattern":"\\bapple\\b","flags":"i","recommended":"Washed whole, sliced or lightly stewed as preferred","why":"Whole apples retain fibre and freshness; cooking gives softness with some heat-sensitive vitamin loss.","important":"The strongest benefit is eating whole fruit regularly, not enforcing a single preparation.","refs":["veg","afcd"],"options":[{"name":"Raw with skin","advantage":"Fibre and crunch.","tradeoff":"Wash thoroughly.","tip":"Cut appropriately."},{"name":"Gently stew","advantage":"Easy digestion and warm flavour.","tradeoff":"Some vitamin C is lost.","tip":"Leave peel if tolerated."},{"name":"Bake","advantage":"Dessert without lots of extra sugar.","tradeoff":"Long heating.","tip":"Use cinnamon."},{"name":"Juice strained","advantage":"Convenient.","tradeoff":"Less fibre and easy to drink large quantities.","tip":"Whole fruit usually better."}],"certainty":"Food-specific evidence mixed; choice is conditional"},{"id":"banana","name":"Bananas","group":"Fruit","pattern":"\\bbanana\\b","flags":"i","recommended":"Eat ripe whole or blend with other whole foods","why":"Ripe banana provides fruit and energy; cooking is a taste choice, not known longevity optimisation.","important":"Blending with oats/soy retains fibre, whereas strained juice is different.","refs":["veg","afcd"],"options":[{"name":"Raw whole","advantage":"No prep, fibre retained.","tradeoff":"Ripeness changes texture and starch.","tip":"Eat to appetite."},{"name":"Blend into smoothie","advantage":"Convenient.","tradeoff":"Drinkable meals may be less filling.","tip":"Keep whole fruit pulp."},{"name":"Bake","advantage":"Adds sweetness without sugar.","tradeoff":"Warmth changes texture and some vitamins.","tip":"Don't add lots of sugar."},{"name":"Pan-fry","advantage":"Sweetens and caramelises.","tradeoff":"Extra oil and scorching.","tip":"Occasional, light cook."}],"certainty":"Food-specific evidence mixed; choice is conditional"},{"id":"kiwi","name":"Kiwifruit","group":"Fruit","pattern":"kiwifruit|kiwi","flags":"i","recommended":"Eat fresh, peeled or washed skin if preferred","why":"Fresh kiwi supplies heat-sensitive vitamin C; cooking isn't needed.","important":"Whole-fruit intake matters more than precise handling; food allergies occur.","refs":["veg","afcd"],"options":[{"name":"Fresh","advantage":"Maintains vitamin C.","tradeoff":"Wash if eating peel.","tip":"Use promptly."},{"name":"Blend","advantage":"Retains fibre if entire flesh used.","tradeoff":"Texture/satiety differs.","tip":"No need to strain."},{"name":"Gently warm / compote","advantage":"Good if soft texture preferred.","tradeoff":"Some vitamin C lost.","tip":"Avoid sugar-heavy sauces."}],"certainty":"Food-specific evidence mixed; choice is conditional"},{"id":"orange","name":"Oranges","group":"Fruit","pattern":"oranges?|navel orange","flags":"i","recommended":"Eat whole segments, not routinely strained juice","why":"Whole orange retains fibre and takes longer to eat.","important":"Heating fruit is not necessary for safety when washed/peeled; juice is not nutritionally identical.","refs":["veg","afcd"],"options":[{"name":"Fresh whole segments","advantage":"Fibre and vitamin C.","tradeoff":"Peel/wash hands.","tip":"Use as recipe fruit."},{"name":"Juice","advantage":"Vitamin C but less fibre.","tradeoff":"More rapid consumption.","tip":"Whole fruit preferred often."},{"name":"Bake into dish","advantage":"Citrus flavour.","tradeoff":"Heat-sensitive vitamin loss.","tip":"Use sparingly."}],"certainty":"Food-specific evidence mixed; choice is conditional"},{"id":"avocado","name":"Avocado","group":"Fruit","pattern":"avocado","flags":"i","recommended":"Eat fresh; warm only gently as preferred","why":"Fresh avocado delivers unsaturated fat and fibre and can replace butter.","important":"Cooking is not needed to 'activate' avocado fat; brown colour alone doesn't quantify nutrient loss.","refs":["fats","afcd"],"options":[{"name":"Fresh smashed / sliced","advantage":"No additional oil needed.","tradeoff":"Ripeness and storage affect texture.","tip":"Cut just before eating."},{"name":"Gentle warm","advantage":"Can work in warm bowls.","tradeoff":"Heat affects texture and flavour.","tip":"Avoid overcooking."},{"name":"Deep-fry","advantage":"Crispy result.","tradeoff":"Coating and added fat.","tip":"Not a default."}],"certainty":"Food-specific evidence mixed; choice is conditional"},{"id":"nuts-butter","name":"Nut butter","group":"Nuts & seeds","pattern":"almond.*butter|peanut butter|nut butter","flags":"i","recommended":"Use unsweetened unsalted spread without heating","why":"Provides fats and some protein; added sugar/salt are more important than heat treatment.","important":"Product and nut allergy labels take priority.","refs":["fats","afcd"],"options":[{"name":"Spread cold","advantage":"No extra cooking oil.","tradeoff":"Energy dense; portion sizes matter.","tip":"Check label."},{"name":"Warm into sauce","advantage":"Good dressing or stir-fry.","tradeoff":"Can stick/burn.","tip":"Heat gently."},{"name":"Bake / toast","advantage":"Works in snacks.","tradeoff":"Added sugar and browned foods.","tip":"Avoid scorching."}],"certainty":"Food-specific evidence mixed; choice is conditional"},{"id":"hummus","name":"Hummus","group":"Legumes","pattern":"hummus","flags":"i","recommended":"Use promptly and store cold; for vulnerable people choose safer freshly cooked option","why":"Chilled hummus is a ready-to-eat food and a practical legume snack for general population.","important":"FSANZ advises avoiding chilled hummus/tahini for some vulnerable groups; do not assume fridge storage removes Listeria risk.","refs":["vulnerable","foodSafety"],"options":[{"name":"Commercial chilled, follow pack","advantage":"Convenient for general healthy adults.","tradeoff":"Higher risk for vulnerable people.","tip":"Keep below 5°C and heed use-by."},{"name":"Freshly made from cooked chickpeas","advantage":"Control salt/ingredients.","tradeoff":"Hygiene and prompt cooling still needed.","tip":"Make small batches."},{"name":"Heat freshly cooked bean mash","advantage":"Safer vulnerable-person alternative.","tradeoff":"Changes texture.","tip":"Use clean cooked beans."},{"name":"Keep on bench for hours","advantage":"No benefit.","tradeoff":"Bacterial growth.","tip":"Avoid."}],"certainty":"Food-specific evidence mixed; choice is conditional"},{"id":"soy-milk","name":"Calcium-fortified soy drink","group":"Fortified foods","pattern":"soy milk|high protein soy|so good","flags":"i","recommended":"Use chilled or gently warmed; check the actual calcium/B12/iodine nutrition panel","why":"Minerals such as calcium do not vanish simply because milk is warmed; processing and product fortification determine coverage.","important":"Do not assume all soy milks contain iodine/B12 or protein equivalently. Keep refrigerated after opening and observe pack.","refs":["afcd","foodSafety"],"options":[{"name":"Drink cold","advantage":"Preserves beverage as labelled.","tradeoff":"Not inherently healthier than heating.","tip":"Check current pack."},{"name":"Gently warm for porridge","advantage":"Practical breakfast.","tradeoff":"Overboiling affects texture, not evidence of 'destroyed calcium'.","tip":"Heat as desired."},{"name":"Blend into smoothie","advantage":"Convenient whole-food ingredients.","tradeoff":"Keep perishable drink cold.","tip":"Avoid excess added sugar."},{"name":"Repeatedly boil to reduce nutrients","advantage":"No demonstrated benefit.","tradeoff":"Unneeded heat, possible texture issues.","tip":"Skip."}],"certainty":"Food-specific evidence mixed; choice is conditional"},{"id":"soy-yoghurt","name":"Fortified soy yoghurt","group":"Fortified foods","pattern":"soy yogh(o|u)rt","flags":"i","recommended":"Eat chilled; heat only if package advises","why":"Nutritional value depends on exact fortification and protein; it isn't equivalent to calcium-fortified soy drink by name.","important":"Live cultures, if present, may not survive heating; shelf life and refrigerated storage matter.","refs":["afcd","foodSafety"],"options":[{"name":"Chilled with fruit","advantage":"Easy snack.","tradeoff":"Some brands low in calcium/protein.","tip":"Read nutrition panel."},{"name":"Add to hot dishes after cooling slightly","advantage":"Creamy topping.","tradeoff":"Heat can affect cultures/texture.","tip":"Avoid prolonged heat."},{"name":"Boil","advantage":"Not useful for texture.","tradeoff":"Cultures can be killed.","tip":"Not routine."}],"certainty":"Food-specific evidence mixed; choice is conditional"},{"id":"bread","name":"Wholegrain bread / toast","group":"Grains","pattern":"wholegrain (?:bread|toast)","flags":"i","recommended":"Eat as bread or lightly toast; prefer high-fibre labelled product","why":"Toasting to very dark brown adds more acrylamide; moderate/light toast preserves convenience.","important":"Gluten-free claim alone doesn't guarantee wholegrains/fibre; dairy allergens vary.","refs":["acry","afcd"],"options":[{"name":"Untoasted","advantage":"No extra heat and no browning.","tradeoff":"Texture preference.","tip":"Check ingredients."},{"name":"Light toast","advantage":"Crisp, convenient.","tradeoff":"Minor browning exposure.","tip":"Toast to lightest acceptable colour."},{"name":"Dark/charred toast","advantage":"No nutrition advantage.","tradeoff":"More acrylamide.","tip":"Avoid regular dark scorching."},{"name":"Fry in butter","advantage":"Rich taste.","tradeoff":"Higher saturated fat.","tip":"Use healthy toppings instead."}],"certainty":"Food-specific evidence mixed; choice is conditional"},{"id":"cinnamon","name":"Cinnamon","group":"Herbs & spices","pattern":"cinnamon","flags":"i","recommended":"Use small amounts in oats or porridge; raw or gently warmed","why":"Adds aroma without sugar; no proven life-extension from cooking cinnamon one way.","important":"Do not consume huge supplement-like quantities or equate cinnamon with glucose medication.","refs":["cooking"],"options":[{"name":"Sprinkle after cooking","advantage":"Strong aroma and no heat exposure.","tradeoff":"Powder can clump.","tip":"Use measured culinary pinch."},{"name":"Simmer in oats","advantage":"Even flavour.","tradeoff":"Long heat may alter volatiles.","tip":"Short cook."},{"name":"Dry toast spice","advantage":"Enhanced flavour.","tradeoff":"Can scorch.","tip":"Very brief."}],"certainty":"Food-specific evidence mixed; choice is conditional"},{"id":"cumin","name":"Cumin","group":"Herbs & spices","pattern":"cumin","flags":"i","recommended":"Bloom briefly in a little oil or simmer","why":"Improves flavour without extra sodium; no human longevity trial ranks spice techniques.","important":"Burned spices taste bitter; supplements aren't equivalent.","refs":["cooking"],"options":[{"name":"Bloom in measured oil","advantage":"Aromatic.","tradeoff":"High heat quickly burns.","tip":"20–40 sec at gentle heat."},{"name":"Simmer in soup","advantage":"Simple.","tradeoff":"Milder flavour.","tip":"Use modest amounts."},{"name":"Add late","advantage":"Bright spice aroma.","tradeoff":"Slightly powdery if undercooked.","tip":"Stir through."}],"certainty":"Food-specific evidence mixed; choice is conditional"},{"id":"coriander","name":"Ground coriander","group":"Herbs & spices","pattern":"ground coriander","flags":"i","recommended":"Briefly bloom or simmer","why":"Cooking changes volatile aromas and supports palatable legume dishes.","important":"No evidence that frying coriander cures inflammation or increases lifespan.","refs":["cooking"],"options":[{"name":"Bloom briefly","advantage":"Fragrant.","tradeoff":"Burn risk.","tip":"Low/medium heat."},{"name":"Simmer","advantage":"Gentle.","tradeoff":"Milder fragrance.","tip":"Mix into sauce."},{"name":"Sprinkle after","advantage":"Strong herbal profile.","tradeoff":"Powder texture.","tip":"Small amounts."}],"certainty":"Food-specific evidence mixed; choice is conditional"},{"id":"paprika","name":"Smoked paprika","group":"Herbs & spices","pattern":"smoked paprika","flags":"i","recommended":"Add to simmering sauce or briefly warm in oil","why":"Gives a smoky taste without needing charring the food itself.","important":"Avoid burning ground paprika. No validated longevity claim for this spice.","refs":["cooking"],"options":[{"name":"Simmer","advantage":"Gentle and practical.","tradeoff":"Less roasted aroma.","tip":"Add with tomatoes."},{"name":"Brief low-heat bloom","advantage":"Aromatic.","tradeoff":"Scorches rapidly.","tip":"Never smoke the oil."},{"name":"Sprinkle cold","advantage":"Strong flavour.","tradeoff":"Powder may taste raw.","tip":"Use modest amount."}],"certainty":"Food-specific evidence mixed; choice is conditional"},{"id":"turmeric","name":"Turmeric","group":"Herbs & spices","pattern":"turmeric","flags":"i","recommended":"Culinary pinch gently simmered or bloomed","why":"Turmeric contributes flavour/colour, but lab curcumin absorption results don't prove everyday longevity benefits.","important":"Supplement-level curcumin doses can have risks, including drug interactions; no need for large doses.","refs":["cooking"],"options":[{"name":"Simmer in curry","advantage":"Easy, moderate temperature.","tradeoff":"Long heat changes colour/aroma.","tip":"Use culinary amount."},{"name":"Brief bloom","advantage":"Flavour and colour.","tradeoff":"Burns if pan too hot.","tip":"Add early briefly."},{"name":"Raw sprinkled","advantage":"Possible.","tradeoff":"Powdery texture.","tip":"Not required."}],"certainty":"Food-specific evidence mixed; choice is conditional"},{"id":"oregano","name":"Oregano","group":"Herbs & spices","pattern":"oregano","flags":"i","recommended":"Add during or toward end of cooking","why":"Herbs improve flavour and help avoid added sodium.","important":"No evidence dried oregano added at a particular minute extends life.","refs":["cooking"],"options":[{"name":"Add to simmer","advantage":"Distributes taste.","tradeoff":"Long simmer changes aromas.","tip":"Use to season sauces."},{"name":"Finish dish","advantage":"Fresher aroma.","tradeoff":"Herb bits visible.","tip":"Crush lightly."},{"name":"Scorch in pan","advantage":"No advantage.","tradeoff":"Bitter flavour.","tip":"Avoid."}],"certainty":"Food-specific evidence mixed; choice is conditional"},{"id":"pepper","name":"Black pepper","group":"Herbs & spices","pattern":"black pepper","flags":"i","recommended":"Use small amount at serving or during simmer","why":"Adds savoury heat without much sodium.","important":"No clinical justification for large pepper or piperine doses to amplify 'superfoods'.","refs":["cooking"],"options":[{"name":"Fresh ground at serving","advantage":"Strong aroma.","tradeoff":"Spiciness tolerance varies.","tip":"Use to taste."},{"name":"Simmer","advantage":"Mellower.","tradeoff":"Aroma changes.","tip":"Small amount."},{"name":"Burn in hot oil","advantage":"No benefit.","tradeoff":"Harsh smoke.","tip":"Avoid."}],"certainty":"Food-specific evidence mixed; choice is conditional"},{"id":"salt","name":"Iodised salt","group":"Fats & seasonings","pattern":"iodised salt|iodized salt|^salt$","flags":"i","recommended":"Limit added salt; select iodised if salt is needed, check other iodine sources","why":"Sodium moderation matters more than whether salt is added before or after cooking; iodine amount can't be assumed from an unspecified pinch.","important":"Iodised salt is not a justification to increase sodium. Australian bread iodisation has exceptions; a high-iodine seaweed substitute is not automatically safe.","refs":["fats","afcd"],"options":[{"name":"Small amount in cooking","advantage":"Even seasoning.","tradeoff":"Adds sodium.","tip":"Taste before adding."},{"name":"Finish with a pinch","advantage":"Direct salty perception.","tradeoff":"Still adds sodium.","tip":"Keep measured."},{"name":"No extra salt","advantage":"Useful with sodium-rich canned sauces.","tradeoff":"Taste depends on herbs/citrus.","tip":"Use lemon and spices."}],"certainty":"Food-specific evidence mixed; choice is conditional"},{"id":"tamari","name":"Reduced-sodium tamari","group":"Fats & seasonings","pattern":"tamari","flags":"i","recommended":"Measure a small amount and dilute with water/citrus","why":"'Reduced sodium' is relative to standard sauce and not necessarily low in sodium.","important":"Read mg sodium per serving on exact product. Brief heating vs uncooked does not reliably solve sodium content.","refs":["fats","cooking"],"options":[{"name":"Measure into sauce","advantage":"Controls sodium.","tradeoff":"Sauce still adds salt.","tip":"Use teaspoons."},{"name":"Add after cooking","advantage":"Strong flavour.","tradeoff":"Salt content unchanged.","tip":"Dilute if needed."},{"name":"Boil to reduce","advantage":"Does not reliably remove sodium.","tradeoff":"Concentrates salty taste as water evaporates.","tip":"Avoid."}],"certainty":"Food-specific evidence mixed; choice is conditional"},{"id":"water","name":"Cooking water","group":"Cooking liquids","pattern":"water for|^water|water, add","flags":"i","recommended":"Use clean water appropriate to food and keep useful cooking liquids","why":"Water contact changes nutrient leaching for vegetables; rice excess-water draining is a special arsenic trade-off.","important":"This is a cooking medium, not a standalone food requiring a 'healthiest preparation'.","refs":["rice","veg","foodSafety"],"options":[{"name":"Minimal-water steam","advantage":"Limits leaching from vegetables.","tradeoff":"Needs correct setup.","tip":"Check water doesn't evaporate."},{"name":"Absorption cooking","advantage":"Retains dissolved food compounds.","tradeoff":"Not an arsenic removal technique.","tip":"Use clean water."},{"name":"Boil and discard","advantage":"Can reduce rice arsenic.","tradeoff":"Leaches other nutrients.","tip":"Use when indicated."},{"name":"Soup / keep broth","advantage":"Retains minerals leached into liquid.","tradeoff":"Salt concentration depends on additions.","tip":"Store safely."}],"certainty":"Food-specific evidence mixed; choice is conditional"},{"id":"cucumber","name":"Cucumber","group":"Vegetables","pattern":"cucumber","flags":"i","recommended":"Washed raw, chilled slices; lightly cooked only if desired","why":"Cucumber is mostly water and is usually eaten raw for crunch. Heating is a culinary option, not a demonstrated longevity upgrade.","important":"Wash well, refrigerate sliced cucumber and follow higher-risk fresh-produce food hygiene. Cut appropriately for small children.","refs":["foodSafety","veg"],"options":[{"name":"Washed raw slices","advantage":"Easy, refreshing, minimal thermal loss.","tradeoff":"Ready-to-eat produce still needs washing and refrigeration.","tip":"Keep cut pieces cold."},{"name":"Quick stir-fry","advantage":"Softens and flavours.","tradeoff":"Alters crisp texture, no proven superior health effect.","tip":"Brief heating."},{"name":"Pickled","advantage":"Interesting taste.","tradeoff":"Commercial pickles can be high sodium.","tip":"Read salt label."},{"name":"Boiled","advantage":"Edible as warm vegetable.","tradeoff":"Watery flavour, soluble nutrient losses.","tip":"Prefer soup if boiling."}],"certainty":"No head-to-head human longevity trials of cucumber preparation"},{"id":"potato","name":"Potatoes","group":"Vegetables","pattern":"potatoes?|root.?veg","flags":"i","recommended":"Boil/steam or bake lightly","why":"Boiling doesn't brown starch; avoid deeply browned roasted/fried potatoes.","important":"Acrylamide rises with deep/high-temperature browning; NSW cooling guidance still applies to cooked potatoes.","refs":["acry","cooking"],"options":[{"name":"Steam / gently simmer","advantage":"Often preserves food without dark browning.","tradeoff":"Water losses vary.","tip":"Use brief heat."},{"name":"Roast / bake","advantage":"Tasty texture.","tradeoff":"Prolonged browning changes heat-sensitive compounds.","tip":"Avoid charring."},{"name":"Raw / chilled","advantage":"May preserve heat-sensitive components.","tradeoff":"Some foods are unsafe raw or unsuitable.","tip":"Follow food-specific safety."},{"name":"Pan-sauté","advantage":"Fast and flavoursome.","tradeoff":"Oil quantity and heat matter.","tip":"Keep modest."}],"certainty":"Food-family context and general safety guidance; no verified head-to-head human lifespan comparison for this ingredient."},{"id":"swede","name":"Swede / turnip","group":"Vegetables","pattern":"swede|turnip","flags":"i","recommended":"Steam or simmer, or roast lightly","why":"Minimise discarded cooking water, or retain in soup.","important":"Very limited direct comparative outcome evidence for swede.","refs":["veg","cooking"],"options":[{"name":"Steam / gently simmer","advantage":"Often preserves food without dark browning.","tradeoff":"Water losses vary.","tip":"Use brief heat."},{"name":"Roast / bake","advantage":"Tasty texture.","tradeoff":"Prolonged browning changes heat-sensitive compounds.","tip":"Avoid charring."},{"name":"Raw / chilled","advantage":"May preserve heat-sensitive components.","tradeoff":"Some foods are unsafe raw or unsuitable.","tip":"Follow food-specific safety."},{"name":"Pan-sauté","advantage":"Fast and flavoursome.","tradeoff":"Oil quantity and heat matter.","tip":"Keep modest."}],"certainty":"Food-family context and general safety guidance; no verified head-to-head human lifespan comparison for this ingredient."},{"id":"broccolini","name":"Broccolini","group":"Vegetables","pattern":"broccolini","flags":"i","recommended":"Brief steam or pan-wilt","why":"Brassica-like vegetable; direct broccoli studies cannot supply exact broccolini retention percentages.","important":"Avoid overcooking, and don't assume raw is safest for everyone.","refs":["broc","veg"],"options":[{"name":"Steam / gently simmer","advantage":"Often preserves food without dark browning.","tradeoff":"Water losses vary.","tip":"Use brief heat."},{"name":"Roast / bake","advantage":"Tasty texture.","tradeoff":"Prolonged browning changes heat-sensitive compounds.","tip":"Avoid charring."},{"name":"Raw / chilled","advantage":"May preserve heat-sensitive components.","tradeoff":"Some foods are unsafe raw or unsuitable.","tip":"Follow food-specific safety."},{"name":"Pan-sauté","advantage":"Fast and flavoursome.","tradeoff":"Oil quantity and heat matter.","tip":"Keep modest."}],"certainty":"Food-family context and general safety guidance; no verified head-to-head human lifespan comparison for this ingredient."},{"id":"corn","name":"Sweetcorn","group":"Vegetables","pattern":"sweetcorn|frozen corn|corn kernels","flags":"i","recommended":"Steam / microwave or boil briefly","why":"Steaming can limit water losses; roasting adds flavour.","important":"Check frozen corn label for whether reheating is required.","refs":["veg","foodSafety"],"options":[{"name":"Steam / gently simmer","advantage":"Often preserves food without dark browning.","tradeoff":"Water losses vary.","tip":"Use brief heat."},{"name":"Roast / bake","advantage":"Tasty texture.","tradeoff":"Prolonged browning changes heat-sensitive compounds.","tip":"Avoid charring."},{"name":"Raw / chilled","advantage":"May preserve heat-sensitive components.","tradeoff":"Some foods are unsafe raw or unsuitable.","tip":"Follow food-specific safety."},{"name":"Pan-sauté","advantage":"Fast and flavoursome.","tradeoff":"Oil quantity and heat matter.","tip":"Keep modest."}],"certainty":"Food-family context and general safety guidance; no verified head-to-head human lifespan comparison for this ingredient."},{"id":"edamame","name":"Edamame / soybeans","group":"Legumes","pattern":"edamame|soybeans","flags":"i","recommended":"Fully cook pods/beans according to pack","why":"Soybean legumes must not be eaten undercooked; steamed/boiled beans retain fibre/protein.","important":"Pods aren't edible soybean grams; defrosting doesn't mean cooked ready-to-eat.","refs":["legume","foodSafety"],"options":[{"name":"Cook in water","advantage":"Hydrates/softens for digestibility.","tradeoff":"Can leach some water-soluble nutrients.","tip":"Cook thoroughly."},{"name":"Pressure-cook","advantage":"Convenient.","tradeoff":"Timing depends on appliance.","tip":"Follow safe directions."},{"name":"Bake/roast after cooking","advantage":"Creates texture.","tradeoff":"Excess dark browning or oil.","tip":"Avoid charring."},{"name":"Raw/uncooked","advantage":"No advantage for dry foods.","tradeoff":"Not an appropriate method for many dry legumes/grains.","tip":"Cook adequately."}],"certainty":"Food-family context and general safety guidance; no verified head-to-head human lifespan comparison for this ingredient."},{"id":"coconut","name":"Coconut cream / coconut milk","group":"Fortified foods","pattern":"coconut cream|coconut milk","flags":"i","recommended":"Measured addition to a gently simmered curry","why":"Simmering makes a sauce but doesn't remove its saturated fat.","important":"Light coconut cream is not a calcium-fortified soy substitute; compare packaged fat per portion.","refs":["fats","afcd"],"options":[{"name":"Steam / gently simmer","advantage":"Often preserves food without dark browning.","tradeoff":"Water losses vary.","tip":"Use brief heat."},{"name":"Roast / bake","advantage":"Tasty texture.","tradeoff":"Prolonged browning changes heat-sensitive compounds.","tip":"Avoid charring."},{"name":"Raw / chilled","advantage":"May preserve heat-sensitive components.","tradeoff":"Some foods are unsafe raw or unsuitable.","tip":"Follow food-specific safety."},{"name":"Pan-sauté","advantage":"Fast and flavoursome.","tradeoff":"Oil quantity and heat matter.","tip":"Keep modest."}],"certainty":"Food-family context and general safety guidance; no verified head-to-head human lifespan comparison for this ingredient."},{"id":"sesame-oil","name":"Sesame oil","group":"Fats & seasonings","pattern":"sesame oil","flags":"i","recommended":"Use measured drizzle after cooking or small sauté amount","why":"Adds flavour/fat; repeated scorching and deep frying adds unnecessary oil exposure.","important":"Sesame allergy can be severe, check product labels.","refs":["fats","cooking"],"options":[{"name":"Use in cold preparation","advantage":"Retains aroma, no extra heating.","tradeoff":"Raw handling and label still matter.","tip":"Keep food safe."},{"name":"Gently simmer / heat","advantage":"Blends flavour.","tradeoff":"Some heat-sensitive compounds change.","tip":"Avoid scorching."},{"name":"Very high-heat fry","advantage":"Crisp/roasted flavour.","tradeoff":"Heat, oil and added sodium affect quality.","tip":"Not the default."}],"certainty":"Food-family context and general safety guidance; no verified head-to-head human lifespan comparison for this ingredient."},{"id":"sesame-seed","name":"Sesame seeds / tahini","group":"Nuts & seeds","pattern":"sesame seeds|tahini","flags":"i","recommended":"Use lightly toasted or fresh, store safely","why":"Light toast brings flavour; extra heating is not a human longevity improvement.","important":"Chilled tahini/hummus has extra rules for some vulnerable people; sesame allergy.","refs":["fats","vulnerable"],"options":[{"name":"Steam / gently simmer","advantage":"Often preserves food without dark browning.","tradeoff":"Water losses vary.","tip":"Use brief heat."},{"name":"Roast / bake","advantage":"Tasty texture.","tradeoff":"Prolonged browning changes heat-sensitive compounds.","tip":"Avoid charring."},{"name":"Raw / chilled","advantage":"May preserve heat-sensitive components.","tradeoff":"Some foods are unsafe raw or unsuitable.","tip":"Follow food-specific safety."},{"name":"Pan-sauté","advantage":"Fast and flavoursome.","tradeoff":"Oil quantity and heat matter.","tip":"Keep modest."}],"certainty":"Food-family context and general safety guidance; no verified head-to-head human lifespan comparison for this ingredient."},{"id":"pepitas","name":"Pumpkin kernels / pepitas","group":"Nuts & seeds","pattern":"pepitas|pumpkin kernels|pumpkin seeds","flags":"i","recommended":"Raw or lightly toasted","why":"Nuts/seeds as a small portion are useful, but heavy frying isn't necessary.","important":"Avoid rancid fats or high-salt coatings; seed allergies are possible.","refs":["fats","afcd"],"options":[{"name":"Steam / gently simmer","advantage":"Often preserves food without dark browning.","tradeoff":"Water losses vary.","tip":"Use brief heat."},{"name":"Roast / bake","advantage":"Tasty texture.","tradeoff":"Prolonged browning changes heat-sensitive compounds.","tip":"Avoid charring."},{"name":"Raw / chilled","advantage":"May preserve heat-sensitive components.","tradeoff":"Some foods are unsafe raw or unsuitable.","tip":"Follow food-specific safety."},{"name":"Pan-sauté","advantage":"Fast and flavoursome.","tradeoff":"Oil quantity and heat matter.","tip":"Keep modest."}],"certainty":"Food-family context and general safety guidance; no verified head-to-head human lifespan comparison for this ingredient."},{"id":"stock","name":"Vegetable / chicken stock","group":"Cooking liquids","pattern":"vegetable stock|chicken stock|low sodium stock|stock powder","flags":"i","recommended":"Simmer in the dish and read sodium label","why":"Retains food-derived cooking liquid; commercial stock sodium varies considerably.","important":"No cooking temperature removes dissolved sodium; check pack and pantry.","refs":["fats","foodSafety"],"options":[{"name":"Use in cold preparation","advantage":"Retains aroma, no extra heating.","tradeoff":"Raw handling and label still matter.","tip":"Keep food safe."},{"name":"Gently simmer / heat","advantage":"Blends flavour.","tradeoff":"Some heat-sensitive compounds change.","tip":"Avoid scorching."},{"name":"Very high-heat fry","advantage":"Crisp/roasted flavour.","tradeoff":"Heat, oil and added sodium affect quality.","tip":"Not the default."}],"certainty":"Food-family context and general safety guidance; no verified head-to-head human lifespan comparison for this ingredient."},{"id":"pasta","name":"Pasta","group":"Grains","pattern":"pasta|spaghetti|macaroni","flags":"i","recommended":"Boil until cooked, reserve modest sauce liquid if desired","why":"Dried pasta requires hydration; wholegrain versions contain more fibre.","important":"Like cooked rice, refrigerate cooked pasta promptly and consume within two days in NSW guidance.","refs":["leftovers","acry"],"options":[{"name":"Cook in water","advantage":"Hydrates/softens for digestibility.","tradeoff":"Can leach some water-soluble nutrients.","tip":"Cook thoroughly."},{"name":"Pressure-cook","advantage":"Convenient.","tradeoff":"Timing depends on appliance.","tip":"Follow safe directions."},{"name":"Bake/roast after cooking","advantage":"Creates texture.","tradeoff":"Excess dark browning or oil.","tip":"Avoid charring."},{"name":"Raw/uncooked","advantage":"No advantage for dry foods.","tradeoff":"Not an appropriate method for many dry legumes/grains.","tip":"Cook adequately."}],"certainty":"Food-family context and general safety guidance; no verified head-to-head human lifespan comparison for this ingredient."},{"id":"tuna","name":"Tuna","group":"Seafood","pattern":"tuna","flags":"i","recommended":"Use commercial canned as supplied or gently cook fresh tuna safely","why":"Canned tuna is already cooked; aggressive re-frying isn't necessary.","important":"Species-specific mercury guidance and safe fish handling vary by age/pregnancy; canned salt is label dependent.","refs":["fish","temps"],"options":[{"name":"Steam/poach","advantage":"Gentle, little oil.","tradeoff":"Texture varies; complete safe cooking still required.","tip":"Use thermometer where relevant."},{"name":"Bake/roast","advantage":"Convenient batch option.","tradeoff":"High heat may dry/char.","tip":"Avoid blackening."},{"name":"Pan-cook","advantage":"Quick and flavoursome.","tradeoff":"Added fats and uneven heating.","tip":"Cook carefully."}],"certainty":"Food-family context and general safety guidance; no verified head-to-head human lifespan comparison for this ingredient."},{"id":"beef","name":"Beef / mince","group":"Protein","pattern":"beef|beef mince|ground beef","flags":"i","recommended":"Stew, bake or pan-cook, use lean cuts, avoid charring","why":"Method should ensure safety, moderate saturated fat and palatability.","important":"Minced meat has stricter cooking guidance than intact steaks. Limit processed meats.","refs":["temps","fats"],"options":[{"name":"Steam/poach","advantage":"Gentle, little oil.","tradeoff":"Texture varies; complete safe cooking still required.","tip":"Use thermometer where relevant."},{"name":"Bake/roast","advantage":"Convenient batch option.","tradeoff":"High heat may dry/char.","tip":"Avoid blackening."},{"name":"Pan-cook","advantage":"Quick and flavoursome.","tradeoff":"Added fats and uneven heating.","tip":"Cook carefully."}],"certainty":"Food-family context and general safety guidance; no verified head-to-head human lifespan comparison for this ingredient."},{"id":"pork","name":"Pork / mince","group":"Protein","pattern":"pork|pork mince","flags":"i","recommended":"Roast or simmer and cook sufficiently","why":"Lean unprocessed pork can be part of varied meals, though plant proteins are valuable swaps.","important":"Minced/rolled meats need thorough cooking; no single pan method confers proven lifespan gains.","refs":["temps","fats"],"options":[{"name":"Steam/poach","advantage":"Gentle, little oil.","tradeoff":"Texture varies; complete safe cooking still required.","tip":"Use thermometer where relevant."},{"name":"Bake/roast","advantage":"Convenient batch option.","tradeoff":"High heat may dry/char.","tip":"Avoid blackening."},{"name":"Pan-cook","advantage":"Quick and flavoursome.","tradeoff":"Added fats and uneven heating.","tip":"Cook carefully."}],"certainty":"Food-family context and general safety guidance; no verified head-to-head human lifespan comparison for this ingredient."},{"id":"turkey","name":"Turkey / mince","group":"Protein","pattern":"turkey|turkey mince","flags":"i","recommended":"Bake, stew or pan-cook to full poultry temperature","why":"Lean poultry alternative; a measured centre temperature matters more than time alone.","important":"Poultry FSANZ centre at least 75°C, including mince. Avoid raw-juice cross-contamination.","refs":["chicken","temps"],"options":[{"name":"Steam/poach","advantage":"Gentle, little oil.","tradeoff":"Texture varies; complete safe cooking still required.","tip":"Use thermometer where relevant."},{"name":"Bake/roast","advantage":"Convenient batch option.","tradeoff":"High heat may dry/char.","tip":"Avoid blackening."},{"name":"Pan-cook","advantage":"Quick and flavoursome.","tradeoff":"Added fats and uneven heating.","tip":"Cook carefully."}],"certainty":"Food-family context and general safety guidance; no verified head-to-head human lifespan comparison for this ingredient."},{"id":"bacon","name":"Bacon / processed meat","group":"Protein","pattern":"bacon","flags":"i","recommended":"Use sparingly; consider replacing with mushrooms/legumes","why":"Substituting processed meat is more important than optimising frying technique.","important":"No way of frying or boiling makes bacon equivalent to unprocessed plant protein.","refs":["fats","cooking"],"options":[{"name":"Steam/poach","advantage":"Gentle, little oil.","tradeoff":"Texture varies; complete safe cooking still required.","tip":"Use thermometer where relevant."},{"name":"Bake/roast","advantage":"Convenient batch option.","tradeoff":"High heat may dry/char.","tip":"Avoid blackening."},{"name":"Pan-cook","advantage":"Quick and flavoursome.","tradeoff":"Added fats and uneven heating.","tip":"Cook carefully."}],"certainty":"Food-family context and general safety guidance; no verified head-to-head human lifespan comparison for this ingredient."},{"id":"cheese","name":"Cheese","group":"Fortified foods","pattern":"cheese|parmesan","flags":"i","recommended":"Use small amount, or dairy-free substitute with checked calcium/protein","why":"Heating melts cheese but doesn't erase saturated fat or dairy allergens.","important":"Choose actually dairy-free products when needed; coconut-style alternatives may be low in protein/calcium.","refs":["fats","afcd"],"options":[{"name":"Steam / gently simmer","advantage":"Often preserves food without dark browning.","tradeoff":"Water losses vary.","tip":"Use brief heat."},{"name":"Roast / bake","advantage":"Tasty texture.","tradeoff":"Prolonged browning changes heat-sensitive compounds.","tip":"Avoid charring."},{"name":"Raw / chilled","advantage":"May preserve heat-sensitive components.","tradeoff":"Some foods are unsafe raw or unsuitable.","tip":"Follow food-specific safety."},{"name":"Pan-sauté","advantage":"Fast and flavoursome.","tradeoff":"Oil quantity and heat matter.","tip":"Keep modest."}],"certainty":"Food-family context and general safety guidance; no verified head-to-head human lifespan comparison for this ingredient."},{"id":"flour","name":"Wheat / plain flour","group":"Grains","pattern":"plain flour|wholemeal flour|wheat flour","flags":"i","recommended":"Bake/cook batter through; use appropriate wholegrain alternatives","why":"Cooking makes raw flour-containing batter safer; wholegrain choice influences fibre.","important":"Raw flour can be microbiologically hazardous. Gluten allergy/coeliac considerations require label checks.","refs":["foodSafety","acry"],"options":[{"name":"Cook in water","advantage":"Hydrates/softens for digestibility.","tradeoff":"Can leach some water-soluble nutrients.","tip":"Cook thoroughly."},{"name":"Pressure-cook","advantage":"Convenient.","tradeoff":"Timing depends on appliance.","tip":"Follow safe directions."},{"name":"Bake/roast after cooking","advantage":"Creates texture.","tradeoff":"Excess dark browning or oil.","tip":"Avoid charring."},{"name":"Raw/uncooked","advantage":"No advantage for dry foods.","tradeoff":"Not an appropriate method for many dry legumes/grains.","tip":"Cook adequately."}],"certainty":"Food-family context and general safety guidance; no verified head-to-head human lifespan comparison for this ingredient."},{"id":"chilli","name":"Chilli flakes / paste","group":"Herbs & spices","pattern":"chilli paste|chilli flakes|fresh chilli|thai red curry paste","flags":"i","recommended":"Simmer/bloom briefly to flavour a dish","why":"Adds flavour; oil/sodium in commercial curry paste varies.","important":"No human lifespan trials rank chilli cooking. Read allergens and sodium.","refs":["cooking","fats"],"options":[{"name":"Use in cold preparation","advantage":"Retains aroma, no extra heating.","tradeoff":"Raw handling and label still matter.","tip":"Keep food safe."},{"name":"Gently simmer / heat","advantage":"Blends flavour.","tradeoff":"Some heat-sensitive compounds change.","tip":"Avoid scorching."},{"name":"Very high-heat fry","advantage":"Crisp/roasted flavour.","tradeoff":"Heat, oil and added sodium affect quality.","tip":"Not the default."}],"certainty":"Food-family context and general safety guidance; no verified head-to-head human lifespan comparison for this ingredient."},{"id":"lime","name":"Lime / juice","group":"Fruit","pattern":"lime juice|lime zest|fresh lime","flags":"i","recommended":"Squeeze fresh or simmer according to recipe","why":"Fresh citrus retains more vitamin C; cooking changes aroma.","important":"No evidence lime before vs after cooking alters lifespan.","refs":["veg","cooking"],"options":[{"name":"Steam / gently simmer","advantage":"Often preserves food without dark browning.","tradeoff":"Water losses vary.","tip":"Use brief heat."},{"name":"Roast / bake","advantage":"Tasty texture.","tradeoff":"Prolonged browning changes heat-sensitive compounds.","tip":"Avoid charring."},{"name":"Raw / chilled","advantage":"May preserve heat-sensitive components.","tradeoff":"Some foods are unsafe raw or unsuitable.","tip":"Follow food-specific safety."},{"name":"Pan-sauté","advantage":"Fast and flavoursome.","tradeoff":"Oil quantity and heat matter.","tip":"Keep modest."}],"certainty":"Food-family context and general safety guidance; no verified head-to-head human lifespan comparison for this ingredient."},{"id":"parsley","name":"Fresh parsley","group":"Herbs & spices","pattern":"parsley","flags":"i","recommended":"Wash and finish dishes fresh, or add near end","why":"Finishing retains some delicate aromas and vitamins.","important":"Leafy herbs are small quantities; don't count a garnish as a daily vegetable serve.","refs":["veg","foodSafety"],"options":[{"name":"Use in cold preparation","advantage":"Retains aroma, no extra heating.","tradeoff":"Raw handling and label still matter.","tip":"Keep food safe."},{"name":"Gently simmer / heat","advantage":"Blends flavour.","tradeoff":"Some heat-sensitive compounds change.","tip":"Avoid scorching."},{"name":"Very high-heat fry","advantage":"Crisp/roasted flavour.","tradeoff":"Heat, oil and added sodium affect quality.","tip":"Not the default."}],"certainty":"Food-family context and general safety guidance; no verified head-to-head human lifespan comparison for this ingredient."}]}; const entries=db.groups.map(g=>({...g,re:new RegExp(g.pattern,g.flags)}));return {...db,entries,match(name){return entries.find(g=>g.re.test(name))||null;},unmatched(names){return names.filter(n=>!entries.some(g=>g.re.test(n)));}};});
